CREATE TABLE users (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,email VARCHAR(190) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,role VARCHAR(80) NOT NULL DEFAULT 'Member',avatar VARCHAR(500),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE rooms (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(160) NOT NULL,service_date DATE NOT NULL,start_time TIME NOT NULL,end_time TIME NOT NULL,code VARCHAR(32) NOT NULL UNIQUE,status ENUM('Scheduled','Live','Completed') NOT NULL DEFAULT 'Scheduled',created_by BIGINT UNSIGNED NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(created_by) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE channels (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(80) NOT NULL UNIQUE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE room_channels (room_id BIGINT UNSIGNED NOT NULL,channel_id BIGINT UNSIGNED NOT NULL,PRIMARY KEY(room_id,channel_id),FOREIGN KEY(room_id) REFERENCES rooms(id) ON DELETE CASCADE,FOREIGN KEY(channel_id) REFERENCES channels(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE team_members (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,room_id BIGINT UNSIGNED NOT NULL,name VARCHAR(120) NOT NULL,role VARCHAR(80) NOT NULL,channel VARCHAR(80) NOT NULL,status ENUM('connected','weak','disconnected','muted','listening') NOT NULL DEFAULT 'disconnected',headset BOOLEAN NOT NULL DEFAULT FALSE,battery TINYINT UNSIGNED NOT NULL DEFAULT 100,last_active TIMESTAMP DEFAULT CURRENT_TIMESTAMP,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(room_id) REFERENCES rooms(id) ON DELETE CASCADE,CHECK(battery<=100),INDEX idx_members_room(room_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE cues (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,label VARCHAR(100) NOT NULL,category VARCHAR(80) NOT NULL,priority ENUM('Normal','High','Emergency') NOT NULL DEFAULT 'Normal',channel VARCHAR(80) NOT NULL DEFAULT 'All Team',icon VARCHAR(100),vibration VARCHAR(100),sort_order INT NOT NULL DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE activity_logs (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,room_id BIGINT UNSIGNED NOT NULL,sender VARCHAR(120) NOT NULL,message VARCHAR(500) NOT NULL,target VARCHAR(80) NOT NULL,received BOOLEAN NOT NULL DEFAULT TRUE,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(room_id) REFERENCES rooms(id) ON DELETE CASCADE,INDEX idx_activity_room_created(room_id,created_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE user_settings (user_id BIGINT UNSIGNED PRIMARY KEY,theme ENUM('dark','light') NOT NULL DEFAULT 'dark',language VARCHAR(10) NOT NULL DEFAULT 'id',notifications BOOLEAN NOT NULL DEFAULT TRUE,vibration BOOLEAN NOT NULL DEFAULT TRUE,audio_device VARCHAR(255) NOT NULL DEFAULT 'Default headset',mic_sensitivity TINYINT UNSIGNED NOT NULL DEFAULT 70,cue_volume TINYINT UNSIGNED NOT NULL DEFAULT 72,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
